const API_BASE_URL = 'https://jsonplaceholder.typicode.com'

/** A blog post as returned by the placeholder API. */
export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

/** A comment attached to a blog post. */
export interface Comment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

export interface GetPostsOptions {
  /** Caps the number of posts returned. */
  limit?: number
  /** Pass `'no-store'` to refetch on every request (the `getServerSideProps` equivalent). */
  cache?: RequestCache
}

/** Fetches the list of posts. */
export async function getPosts({
  limit,
  cache,
}: GetPostsOptions = {}): Promise<Post[]> {
  const url = new URL('/posts', API_BASE_URL)
  if (limit !== undefined) {
    url.searchParams.set('_limit', String(limit))
  }

  const res = await fetch(url, { cache })
  if (!res.ok) {
    throw new Error(`Failed to fetch posts (${res.status})`)
  }

  return res.json()
}

/** Fetches a single post, or `null` when it does not exist. */
export async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`${API_BASE_URL}/posts/${encodeURIComponent(id)}`)
  if (res.status === 404) {
    return null
  }
  if (!res.ok) {
    throw new Error(`Failed to fetch post ${id} (${res.status})`)
  }

  return res.json()
}

/** Fetches the comments for a post. */
export async function getComments(postId: string): Promise<Comment[]> {
  const res = await fetch(
    `${API_BASE_URL}/posts/${encodeURIComponent(postId)}/comments`
  )
  if (!res.ok) {
    throw new Error(`Failed to fetch comments for post ${postId} (${res.status})`)
  }

  return res.json()
}

