// dynamic rendering, and `cache: 'no-store'` refetches the posts per request.
export default async function HomePage() {
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') ?? ''
  const posts = await getPosts({ limit: 5, cache: 'no-store' })
