import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import { getComments, getPost, getPosts } from '@/lib/posts'

// Replaces `getStaticProps` + `revalidate: 300` (5 minutes).
export const revalidate = 300

// Replaces `fallback: 'blocking'` from `getStaticPaths`. Params outside of
// `generateStaticParams` are rendered on demand and then cached; set this to
// `false` to return a 404 for them instead.
export const dynamicParams = true

// Replaces `getStaticPaths`.
export async function generateStaticParams() {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({
    id: String(post.id),
  }))
}

// Replaces the `<Head>` tags that depended on the fetched post.
export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
