'use client' // Error boundaries must be Client Components

import '@/styles/globals.css'

export interface GlobalErrorProps {
  error: Error & { digest?: string }
  retry: () => void
}

// Handles errors thrown by the root layout itself, which `error.tsx` cannot
// catch. It replaces the root layout when active, so it renders its own
// document and imports the global styles.
export default function GlobalError({ error, retry }: GlobalErrorProps) {
  return (
    <html lang="en">
      <body>
        {/* Error boundaries can't export `metadata`, so the title is set with
            React's <title> component, which is hoisted into <head>. */}
        <title>Error - My Blog</title>
        <div className="error-page">
          <h1>An error occurred</h1>
          <p>Sorry, something went wrong.</p>
          {error.digest ? <p>Error reference: {error.digest}</p> : null}
          <button type="button" onClick={() => retry()}>
            Try again
          </button>
        </div>
      </body>
    </html>
  )
}

