/** A post as exposed by the `/api/posts` route handlers. */
export interface ApiPost {
  id: number
  title: string
  content: string
}

export interface CreatedPost extends ApiPost {
  createdAt: string
}

export interface UpdatedPost extends ApiPost {
  updatedAt: string
}

export interface ApiError {
  error: string
}

/** Request body accepted by `POST /api/posts` and `PUT /api/posts/[id]`. */
export interface PostInput {
  title?: string
  content?: string
}

/**
 * Reads a JSON request body without trusting its shape. `Request.json()` returns
 * `any` and throws on malformed JSON, so callers get `null` instead.
 */
export async function readPostInput(request: Request): Promise<PostInput | null> {
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return null
  }

  if (typeof body !== 'object' || body === null) {
    return null
  }

  const { title, content } = body as Record<string, unknown>

  return {
    title: typeof title === 'string' ? title : undefined,
    content: typeof content === 'string' ? content : undefined,
  }
}

