import { NextResponse, type NextRequest } from 'next/server'
import {
  readPostInput,
  type ApiError,
  type ApiPost,
  type CreatedPost,
} from './types'

// Replaces `pages/api/posts/index.js`. Each HTTP method is its own export;
// Next.js answers unsupported methods with a 405 and an `Allow` header, so the
// manual method check from the API route is no longer needed.

export async function GET(): Promise<NextResponse<ApiPost[]>> {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts)
}

export async function POST(
  request: NextRequest
): Promise<NextResponse<CreatedPost | ApiError>> {
  const input = await readPostInput(request)

  if (!input?.title || !input.content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: CreatedPost = {
    id: Date.now(),
    title: input.title,
    content: input.content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

