import { NextResponse, type NextRequest } from 'next/server'
import {
  readPostInput,
  type CreatedPost,
  type UpdatedPost,
} from '../types'

// Replaces `pages/api/posts/[id].js`. The dynamic segment arrives on the route
// context as a promise (`req.query` no longer exists in the App Router).

export async function GET(
  _request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
): Promise<NextResponse<CreatedPost>> {
  const { id } = await ctx.params

  // Simulate fetching a single post
  const post: CreatedPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(
  request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
): Promise<NextResponse<UpdatedPost>> {
  const { id } = await ctx.params
  const input = await readPostInput(request)

  // Simulate updating a post
  const updatedPost: UpdatedPost = {
    id: parseInt(id, 10),
    title: input?.title || `Post ${id}`,
    content: input?.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
): Promise<NextResponse<{ message: string }>> {
  const { id } = await ctx.params

  // Simulate deleting a post
  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

